36	type silentShortWriter struct {
37		buf bytes.Buffer
38	}
39	
40	func (w *silentShortWriter) Write(p []byte) (int, error) {
41		n := len(p) / 2
42		w.buf.Write(p[:n])
43		return n, nil
44	}
