301		}
302		if !strings.Contains(r.out, `"insufficient_balance"`) || !strings.HasSuffix(r.out, "\n") {
303			t.Fatalf("out=%q", r.out)
304		}
305		// 合法空批次仍返回原有空列表。
306		r = runCLIWith(t, []string{"submit", "-l", ledgerPath}, `{"fee_bps":0,"intents":[]}`)
307		if r.code != 0 || strings.TrimSpace(r.out) != "{\n  \"results\": []\n}" {
